{
  "schemaVersion": "advisor-proof/1",
  "buyer": {
    "segment": "Owner-operated professional course businesses that recently finished a cohort and are promoting another.",
    "buyingProblemOrTrigger": "The owner needs fresh graduate testimonials for the next enrollment page and controls both customer communication and purchasing.",
    "whyChosen": "A completed cohort provides people to ask, while another enrollment cycle creates a timely use for proof. This is a narrower first buyer than general marketers, whose authority and immediate need are harder to establish."
  },
  "channel": {
    "name": "Manual LinkedIn contextual outreach",
    "whereAndHow": "Search Posts for combinations of “cohort,” “wrapped up,” “graduates,” and “next cohort,” using the past-month filter where available. Inspect authors’ profiles and linked course pages; approach only identifiable course owners through permitted free messaging or connection requests.",
    "whyChosen": "Public cohort updates can expose a relevant trigger without assuming an existing network. This is preferable to publishing general testimonial advice first: no prior channel effort is reported, and publication would require attracting the right audience before testing buying interest."
  },
  "tasks": [
    {
      "instruction": "Check Senja’s current signup, collection, website-sharing, and payment paths. Identify what actually requires payment before discussing an upgrade.",
      "activityToRecord": "Record verified steps, restrictions, and the first useful product event.",
      "minutes": 25,
      "directCost": 0
    },
    {
      "instruction": "Find up to eight matching owners through the specified LinkedIn searches. Exclude student posts and businesses without a visible next enrollment cycle.",
      "activityToRecord": "Record source links, owner authority, cohort timing, and available free contact routes.",
      "minutes": 40,
      "directCost": 0
    },
    {
      "instruction": "Prepare one short message, then personalize and send up to eight permitted approaches. Reference the cohort update, ask how they collect graduate proof, and offer Senja only when relevant. Avoid generic promotional comments.",
      "activityToRecord": "Record approaches sent, connection requests, and delivery limitations separately.",
      "minutes": 45,
      "directCost": 0
    },
    {
      "instruction": "Handle replies across the week. Invite interested owners to use the existing SaaS themselves; ask permission to check progress. Discuss payment only against the verified offer.",
      "activityToRecord": "Record needs, objections, useful activation, repeated use, and confirmed payment separately.",
      "minutes": 45,
      "directCost": 0
    },
    {
      "instruction": "Review the evidence on day seven and choose the next iteration.",
      "activityToRecord": "Summarize reachable prospects, conversations, product progress, and reasons for stopping.",
      "minutes": 25,
      "directCost": 0
    }
  ],
  "resources": {
    "availableMinutes": 180,
    "experimentBudget": 0,
    "currency": "USD",
    "basis": "The hypothetical context supplies three weekly hours, zero monthly budget, a launched product without paying customers, and no previous acquisition efforts. All work uses free access."
  },
  "successCriteria": {
    "evidenceToCollect": "Distinguish replies from qualified interest: an owner confirms a current collection problem and agrees to evaluate Senja. Activation means obtaining a real testimonial or publishing existing proof; adoption requires subsequent use. Neither establishes payment.",
    "continueWhen": "Provisionally continue if two owners express qualified interest and one activates; investigate whether the verified paid offer solves a remaining need.",
    "adjustWhen": "Change messaging or onboarding when replies reveal relevance but unclear value or activation friction.",
    "reconsiderWhen": "Reconsider targeting if conversations repeatedly show no timely need; reconsider access if free contact routes are unavailable. Silence after one week is inconclusive."
  },
  "importantUnknowns": [
    "Current pricing and paid-feature boundaries.",
    "Whether enough matching owners are reachable through free LinkedIn access."
  ],
  "productEvidenceIds": ["s1", "s3", "s4"]
}

